codes.python:
class TextEditor:
    def bold(self):
        print("Applying bold formatting")

    def italic(self):
        print("Applying italic formatting")

    def unbold(self):
        print("Removing bold formatting")


from abc import ABC, abstractmethod


class Command(ABC):
    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def undo(self):
        pass


class BoldCommand(Command):
    def __init__(self, text_editor):
        self.text_editor = text_editor

    def execute(self):
        self.text_editor.bold()

    def undo(self):
        self.text_editor.unbold()


class ItalicCommand(Command):
    def __init__(self, text_editor):
        self.text_editor = text_editor

    def execute(self):
        self.text_editor.italic()

    def undo(self):
        print("Removing italic formatting")


if __name__ == "__main__":
    text_editor = TextEditor()
    queue = []

    # Each action is an object
    bold = BoldCommand(text_editor)
    italic = ItalicCommand(text_editor)

    # Execute
    bold.execute()

    # Undo
    bold.undo()

    # Queue for later
    queue.append(italic)

