    }

    public void unbold() {
        System.out.println("Removing bold formatting");
    }
}

interface Command {
    void execute();
    void undo();
}

class BoldCommand implements Command {
    private final TextEditor textEditor;

    public BoldCommand(TextEditor textEditor) {
        this.textEditor = textEditor;
    }

    @Override
    public void execute() { textEditor.bold(); }

    @Override
    public void undo() { textEditor.unbold(); }
}

class ItalicCommand implements Command {
    private final TextEditor textEditor;

    public ItalicCommand(TextEditor textEditor) {
        this.textEditor = textEditor;
    }

    @Override
    public void execute() { textEditor.italic(); }

    @Override
    public void undo() { System.out.println("Removing italic formatting"); }
}

public class Main {
    public static void main(String[] args) {
        TextEditor textEditor = new TextEditor();
        List<Command> queue = new ArrayList<>();

        // Each action is an object
        Command bold   = new BoldCommand(textEditor);
        Command italic = new ItalicCommand(textEditor);

        // Execute
        bold.execute();

        // Undo
        bold.undo();

        // Queue for later
        queue.add(italic);
    }
}

codes.cpp:
#include <bits/stdc++.h>
using namespace std;

class TextEditor {
public:
    void bold() { cout << "Applying bold formatting" << endl; }
    void italic() { cout << "Applying italic formatting" << endl; }
    void unbold() { cout << "Removing bold formatting" << endl; }
};

class Command {
public:
    virtual void execute() = 0;
    virtual void undo() = 0;
    virtual ~Command() = default;
};

class BoldCommand : public Command {
    TextEditor& textEditor;
public:
    BoldCommand(TextEditor& textEditor) : textEditor(textEditor) {}

    void execute() override { textEditor.bold(); }
    void undo() override { textEditor.unbold(); }
};

class ItalicCommand : public Command {
    TextEditor& textEditor;
public:
    ItalicCommand(TextEditor& textEditor) : textEditor(textEditor) {}

    void execute() override { textEditor.italic(); }
    void undo() override { cout << "Removing italic formatting" << endl; }
};

int main() {
    TextEditor textEditor;
    vector<Command*> queue;

    // Each action is an object
    BoldCommand bold(textEditor);
    ItalicCommand italic(textEditor);

    // Execute
    bold.execute();

    // Undo
    bold.undo();

    // Queue for later
    queue.push_back(&italic);
    return 0;
}

