        System.out.println("Dessert: Preparing " + dessert);
    }
}

class WaiterNaive {
    private final Kitchen kitchen;
    private final Bar bar;
    private final DessertCounter dessert;

    public WaiterNaive(Kitchen kitchen, Bar bar, DessertCounter dessert) {
        this.kitchen = kitchen;
        this.bar     = bar;
        this.dessert = dessert;
    }

    public void placeKitchenOrder(String meal) {
        kitchen.cookMeal(meal);
    }

    public void placeBarOrder(String drink) {
        bar.prepareDrink(drink);
    }

    public void placeDessertOrder(String item) {
        dessert.prepareDessert(item);
    }
}

public class Main {
    public static void main(String[] args) {
        Kitchen kitchen = new Kitchen();
        Bar bar         = new Bar();
        DessertCounter dessert = new DessertCounter();

        WaiterNaive waiter = new WaiterNaive(kitchen, bar, dessert);
        waiter.placeKitchenOrder("Pasta");
        waiter.placeBarOrder("Juice");
        waiter.placeDessertOrder("Cake");
    }
}

