import java.util.HashMap;
import java.util.Map;
import java.util.Stack;

// Receiver
class ShoppingCart {
    private final Map<String, Double> items = new HashMap<>();
    private double total = 0;

    public void addItem(String item, double price) {
        items.put(item, price);
        total += price;
        System.out.println("Cart: Added " + item + " ($" + price + ")");
    }

    public void removeItem(String item) {
        if (items.containsKey(item)) {
            total -= items.get(item);
            items.remove(item);
            System.out.println("Cart: Removed " + item);
        }
    }

    public void applyDiscount(double percent) {
        double discount = total * (percent / 100);
        total -= discount;
        System.out.println("Cart: Applied " + percent + "% discount. Saved $" + discount);
    }

    public void reverseDiscount(double percent) {
        total = total / (1 - percent / 100);
        System.out.println("Cart: Reversed " + percent + "% discount.");
    }

    public double getTotal()  { return Math.round(total * 100.0) / 100.0; }

    public void printCart() {
        System.out.println("Cart Contents: " + items);
        System.out.println("Total: $" + getTotal());
    }
}

// Command Interface
interface CartCommand {
    void execute();
    void undo();
}

// Concrete Commands
class AddItemCommand implements CartCommand {
    private final ShoppingCart cart;
    private final String item;
    private final double price;

    public AddItemCommand(ShoppingCart cart, String item, double price) {
        this.cart  = cart;
        this.item  = item;
        this.price = price;
    }

    @Override
    public void execute() { cart.addItem(item, price);  }

    @Override
    public void undo()    { cart.removeItem(item);      }
}

class RemoveItemCommand implements CartCommand {
    private final ShoppingCart cart;
    private final String item;
    private final double price;

    public RemoveItemCommand(ShoppingCart cart, String item, double price) {
        this.cart  = cart;
        this.item  = item;
        this.price = price;
    }

    @Override
    public void execute() { cart.removeItem(item);      }

    @Override
    public void undo()    { cart.addItem(item, price);  }
}

class ApplyDiscountCommand implements CartCommand {
    private final ShoppingCart cart;
    private final double percent;

    public ApplyDiscountCommand(ShoppingCart cart, double percent) {
        this.cart    = cart;
        this.percent = percent;
    }

    @Override
    public void execute() { cart.applyDiscount(percent);        }

    @Override
    public void undo()    { cart.reverseDiscount(percent);      }
}

// Invoker
class CartInvoker {
    private final Stack<CartCommand> undoStack = new Stack<>();
    private final Stack<CartCommand> redoStack = new Stack<>();

    public void execute(CartCommand command) {
        command.execute();
        undoStack.push(command);
        redoStack.clear();
    }

    public void undo() {
        if (!undoStack.isEmpty()) {
            CartCommand command = undoStack.pop();
            command.undo();
            redoStack.push(command);
        } else {
            System.out.println("Nothing to undo.");
        }
    }

    public void redo() {
        if (!redoStack.isEmpty()) {
            CartCommand command = redoStack.pop();
            command.execute();
            undoStack.push(command);
        } else {
            System.out.println("Nothing to redo.");
        }
    }
}

// Client
public class Main {
    public static void main(String[] args) {
        ShoppingCart cart    = new ShoppingCart();
        CartInvoker  invoker = new CartInvoker();

        System.out.println("--- Adding Items ---");
        invoker.execute(new AddItemCommand(cart, "Laptop",  999.99));
        invoker.execute(new AddItemCommand(cart, "Mouse",    29.99));
        invoker.execute(new AddItemCommand(cart, "Keyboard", 79.99));
        cart.printCart();

        System.out.println("\n--- Applying Discount ---");
        invoker.execute(new ApplyDiscountCommand(cart, 10));
        cart.printCart();

        System.out.println("\n--- Undo Discount ---");
        invoker.undo();
        cart.printCart();

        System.out.println("\n--- Undo Add Keyboard ---");
        invoker.undo();
        cart.printCart();

        System.out.println("\n--- Redo Add Keyboard ---");
        invoker.redo();
        cart.printCart();

        System.out.println("\n--- Remove Item ---");
        invoker.execute(new RemoveItemCommand(cart, "Mouse", 29.99));
        cart.printCart();

        System.out.println("\n--- Undo Remove ---");
        invoker.undo();
        cart.printCart();

        System.out.println("\n--- Redo clears after new action ---");
        invoker.redo();
        System.out.println("Nothing to redo.");
    }
}

