from abc import ABC, abstractmethod


# Receiver
class ShoppingCart:
    def __init__(self):
        self.items = {}
        self.total = 0

    def add_item(self, item, price):
        self.items[item] = price
        self.total += price
        print(f"Cart: Added {item} (${price})")

    def remove_item(self, item):
        if item in self.items:
            self.total -= self.items[item]
            del self.items[item]
            print(f"Cart: Removed {item}")

    def apply_discount(self, percent):
        discount = self.total * (percent / 100)
        self.total -= discount
        print(f"Cart: Applied {percent}% discount. Saved ${discount}")

    def reverse_discount(self, percent):
        self.total = self.total / (1 - percent / 100)
        print(f"Cart: Reversed {percent}% discount.")

    def get_total(self):
        return round(self.total, 2)

    def print_cart(self):
        print(f"Cart Contents: {self.items}")
        print(f"Total: ${self.get_total()}")


# Command Interface
class CartCommand(ABC):
    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def undo(self):
        pass


# Concrete Commands
class AddItemCommand(CartCommand):
    def __init__(self, cart, item, price):
        self.cart = cart
        self.item = item
        self.price = price

    def execute(self):
        self.cart.add_item(self.item, self.price)

    def undo(self):
        self.cart.remove_item(self.item)


class RemoveItemCommand(CartCommand):
    def __init__(self, cart, item, price):
        self.cart = cart
        self.item = item
        self.price = price

    def execute(self):
        self.cart.remove_item(self.item)

    def undo(self):
        self.cart.add_item(self.item, self.price)


class ApplyDiscountCommand(CartCommand):
    def __init__(self, cart, percent):
        self.cart = cart
        self.percent = percent

    def execute(self):
        self.cart.apply_discount(self.percent)

    def undo(self):
        self.cart.reverse_discount(self.percent)


# Invoker
class CartInvoker:
    def __init__(self):
        self.undo_stack = []
        self.redo_stack = []

    def execute(self, command):
        command.execute()
        self.undo_stack.append(command)
        self.redo_stack.clear()

    def undo(self):
        if self.undo_stack:
            command = self.undo_stack.pop()
            command.undo()
            self.redo_stack.append(command)
        else:
            print("Nothing to undo.")

    def redo(self):
        if self.redo_stack:
            command = self.redo_stack.pop()
            command.execute()
            self.undo_stack.append(command)
        else:
            print("Nothing to redo.")


# Client
if __name__ == "__main__":
    cart = ShoppingCart()
    invoker = CartInvoker()

    print("--- Adding Items ---")
    invoker.execute(AddItemCommand(cart, "Laptop", 999.99))
    invoker.execute(AddItemCommand(cart, "Mouse", 29.99))
    invoker.execute(AddItemCommand(cart, "Keyboard", 79.99))
    cart.print_cart()

    print("\n--- Applying Discount ---")
    invoker.execute(ApplyDiscountCommand(cart, 10))
    cart.print_cart()

    print("\n--- Undo Discount ---")
    invoker.undo()
    cart.print_cart()

    print("\n--- Undo Add Keyboard ---")
    invoker.undo()
    cart.print_cart()

    print("\n--- Redo Add Keyboard ---")
    invoker.redo()
    cart.print_cart()

    print("\n--- Remove Item ---")
    invoker.execute(RemoveItemCommand(cart, "Mouse", 29.99))
    cart.print_cart()

    print("\n--- Undo Remove ---")
    invoker.undo()
    cart.print_cart()

    print("\n--- Redo clears after new action ---")
    invoker.redo()
    print("Nothing to redo.")

