#include <bits/stdc++.h>
using namespace std;

// Receiver
class ShoppingCart {
    map<string, double> items;
    double total = 0;
public:
    void addItem(const string& item, double price) {
        items[item] = price;
        total += price;
        cout << "Cart: Added " << item << " ($" << price << ")" << endl;
    }

    void removeItem(const string& item) {
        if (items.count(item)) {
            total -= items[item];
            items.erase(item);
            cout << "Cart: Removed " << item << endl;
        }
    }

    void applyDiscount(double percent) {
        double discount = total * (percent / 100);
        total -= discount;
        cout << "Cart: Applied " << percent << "% discount. Saved $" << discount << endl;
    }

    void reverseDiscount(double percent) {
        total = total / (1 - percent / 100);
        cout << "Cart: Reversed " << percent << "% discount." << endl;
    }

    double getTotal() { return round(total * 100.0) / 100.0; }

    void printCart() {
        cout << "Cart Contents: {";
        bool first = true;
        for (auto& [item, price] : items) {
            if (!first) cout << ", ";
            cout << item << "=" << price;
            first = false;
        }
        cout << "}" << endl;
        cout << "Total: $" << getTotal() << endl;
    }
};

// Command Interface
class CartCommand {
public:
    virtual void execute() = 0;
    virtual void undo() = 0;
    virtual ~CartCommand() = default;
};

// Concrete Commands
class AddItemCommand : public CartCommand {
    ShoppingCart& cart;
    string item;
    double price;
public:
    AddItemCommand(ShoppingCart& cart, string item, double price) : cart(cart), item(item), price(price) {}

    void execute() override { cart.addItem(item, price); }
    void undo() override { cart.removeItem(item); }
};

class RemoveItemCommand : public CartCommand {
    ShoppingCart& cart;
    string item;
    double price;
public:
    RemoveItemCommand(ShoppingCart& cart, string item, double price) : cart(cart), item(item), price(price) {}

    void execute() override { cart.removeItem(item); }
    void undo() override { cart.addItem(item, price); }
};

class ApplyDiscountCommand : public CartCommand {
    ShoppingCart& cart;
    double percent;
public:
    ApplyDiscountCommand(ShoppingCart& cart, double percent) : cart(cart), percent(percent) {}

    void execute() override { cart.applyDiscount(percent); }
    void undo() override { cart.reverseDiscount(percent); }
};

// Invoker
class CartInvoker {
    vector<CartCommand*> undoStack;
    vector<CartCommand*> redoStack;
public:
    void execute(CartCommand* command) {
        command->execute();
        undoStack.push_back(command);
        redoStack.clear();
    }

    void undo() {
        if (!undoStack.empty()) {
            CartCommand* command = undoStack.back();
            undoStack.pop_back();
            command->undo();
            redoStack.push_back(command);
        } else {
            cout << "Nothing to undo." << endl;
        }
    }

    void redo() {
        if (!redoStack.empty()) {
            CartCommand* command = redoStack.back();
            redoStack.pop_back();
            command->execute();
            undoStack.push_back(command);
        } else {
            cout << "Nothing to redo." << endl;
        }
    }
};

// Client
int main() {
    ShoppingCart cart;
    CartInvoker invoker;

    cout << "--- Adding Items ---" << endl;
    AddItemCommand addLaptop(cart, "Laptop", 999.99);
    AddItemCommand addMouse(cart, "Mouse", 29.99);
    AddItemCommand addKeyboard(cart, "Keyboard", 79.99);
    invoker.execute(&addLaptop);
    invoker.execute(&addMouse);
    invoker.execute(&addKeyboard);
    cart.printCart();

    cout << endl << "--- Applying Discount ---" << endl;
    ApplyDiscountCommand discount(cart, 10);
    invoker.execute(&discount);
    cart.printCart();

    cout << endl << "--- Undo Discount ---" << endl;
    invoker.undo();
    cart.printCart();

    cout << endl << "--- Undo Add Keyboard ---" << endl;
    invoker.undo();
    cart.printCart();

    cout << endl << "--- Redo Add Keyboard ---" << endl;
    invoker.redo();
    cart.printCart();

    cout << endl << "--- Remove Item ---" << endl;
    RemoveItemCommand removeMouse(cart, "Mouse", 29.99);
    invoker.execute(&removeMouse);
    cart.printCart();

    cout << endl << "--- Undo Remove ---" << endl;
    invoker.undo();
    cart.printCart();

    cout << endl << "--- Redo clears after new action ---" << endl;
    invoker.redo();
    cout << "Nothing to redo." << endl;

    return 0;
}
